CREATE OR REPLACE FUNCTION public.has_any_role(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id IS NOT NULL AND _user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id) $$;
CREATE OR REPLACE FUNCTION public.is_admin_or_financeiro(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id IS NOT NULL AND _user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('admin','financeiro')) $$;
CREATE OR REPLACE FUNCTION public.is_admin_or_gestor(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id IS NOT NULL AND _user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('admin','gestor')) $$;
